use crate::common;
use rust_xlsxwriter::{
    Color, ConditionalFormatCell, ConditionalFormatCellRule, Format, Workbook, XlsxError,
};

// Test the rule priorities when a range is repeated after a different range.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    for row in 0..5 {
        worksheet.write(row, 0, 1)?;
        worksheet.write(row, 1, row)?;
    }

    let format1 = Format::new().set_background_color(Color::Red);
    let format2 = Format::new().set_background_color(Color::Blue);
    let format3 = Format::new().set_background_color(Color::Green);

    // Manually set the indices to get the same order as the target file.
    worksheet.format_dxf_index(&format2);
    worksheet.format_dxf_index(&format3);
    worksheet.format_dxf_index(&format1);

    let conditional_format = ConditionalFormatCell::new()
        .set_rule(ConditionalFormatCellRule::GreaterThan(5))
        .set_format(&format1);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    let conditional_format = ConditionalFormatCell::new()
        .set_rule(ConditionalFormatCellRule::GreaterThan(0))
        .set_format(&format2);

    worksheet.add_conditional_format(0, 0, 4, 1, &conditional_format)?;

    let conditional_format = ConditionalFormatCell::new()
        .set_rule(ConditionalFormatCellRule::GreaterThan(0))
        .set_format(&format3);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_cond_format23() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format23")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
